//! gri-mech 3.0 thermochemistry: the nasa-7 evaluations over the
//! mechanism's own species set.
//!
//! the coefficients live in `gri30_thermo.rs`, generated by
//! `tools/gen_gri30_tables.py` from cantera's distribution copy of the
//! mechanism. this module evaluates them.
//!
//! unlike the nine-species hydrogen fit, where every species switches
//! at 1000 K, the fifty-three-species mechanism carries a switch
//! temperature per species: twenty-seven species use 1000 K, while
//! the rest use their own midpoint (1382 K for NC, 1368 K for NH,
//! 1478 K for NO, and so on). the switch is honoured per species.
//!
//! the polynomials are dimensioned in the customary way: cp/R,
//! h/(R T) and s/R, with the standard state at 1 atm.

use crate::gri30_thermo::{
    MOLECULAR_MASS, NASA_COEFFS, NS_GRI30, SPECIES_NAMES, TEMPERATURE_RANGES,
};

/// molar gas constant, J/(kmol K).
///
/// the mechanism's own polynomials divide by a gas constant in J per
/// mole-kelvin when they express entropy and enthalpy, so the tables
/// are read in the kmol basis and divided by `RU_KMOL` here. keeping the
/// kmol basis throughout lets molar masses stay kg/kmol, which is the
/// basis the mass fractions in the solver already use.
pub const RU_KMOL: f64 = 8314.462618;

/// standard-state pressure, 1 atm in pascal.
pub const P0: f64 = 101_325.0;

/// the polynomial coefficients for species `s` at temperature `t`.
#[inline]
fn coeffs(s: usize, t: f64) -> [f64; 7] {
    let flat = &NASA_COEFFS[s];
    let bounds = TEMPERATURE_RANGES[s];
    let high = t >= bounds[1];
    let base = if high { 7 } else { 0 };
    [
        flat[base],
        flat[base + 1],
        flat[base + 2],
        flat[base + 3],
        flat[base + 4],
        flat[base + 5],
        flat[base + 6],
    ]
}

/// cp/R for species `s` at temperature `t`.
#[inline]
pub fn cp_r(s: usize, t: f64) -> f64 {
    let t = t.max(200.0);
    let a = coeffs(s, t);
    a[0] + a[1] * t + a[2] * t * t + a[3] * t * t * t + a[4] * t * t * t * t
}

/// h/(R T) for species `s` at temperature `t`, the formation enthalpy
/// included.
#[inline]
pub fn h_rt(s: usize, t: f64) -> f64 {
    let t = t.max(200.0);
    let a = coeffs(s, t);
    a[0] + a[1] * t / 2.0
        + a[2] * t * t / 3.0
        + a[3] * t.powi(3) / 4.0
        + a[4] * t.powi(4) / 5.0
        + a[5] / t
}

/// s/R for species `s` at temperature `t`, the 1 atm standard state.
#[inline]
pub fn s_r(s: usize, t: f64) -> f64 {
    let t = t.max(200.0);
    let a = coeffs(s, t);
    a[0] * t.ln()
        + a[1] * t
        + a[2] * t * t / 2.0
        + a[3] * t.powi(3) / 3.0
        + a[4] * t.powi(4) / 4.0
        + a[6]
}

/// g/(R T) for species `s` at temperature `t`.
#[inline]
pub fn g_rt(s: usize, t: f64) -> f64 {
    h_rt(s, t) - s_r(s, t)
}

/// molar mass of species `s`, kg/kmol.
#[inline]
pub fn molar_mass(s: usize) -> f64 {
    MOLECULAR_MASS[s]
}

/// index of a species by name, or `None` when the mechanism has no
/// such species.
pub fn species_index(name: &str) -> Option<usize> {
    SPECIES_NAMES
        .iter()
        .position(|candidate| *candidate == name)
}

/// cp of species `s` at temperature `t`, J/(kg K).
#[inline]
pub fn cp_mass(s: usize, t: f64) -> f64 {
    cp_r(s, t) * RU_KMOL / MOLECULAR_MASS[s]
}

/// enthalpy of species `s` at temperature `t`, J/kg.
#[inline]
pub fn h_mass(s: usize, t: f64) -> f64 {
    h_rt(s, t) * RU_KMOL * t / MOLECULAR_MASS[s]
}

/// mixture cp from mass fractions, J/(kg K).
pub fn mix_cp_mass(y: &[f64; NS_GRI30], t: f64) -> f64 {
    let mut total = 0.0;
    for (s, mass) in y.iter().enumerate() {
        if *mass != 0.0 {
            total += mass * cp_mass(s, t);
        }
    }
    total
}

/// mixture enthalpy from mass fractions, J/kg.
pub fn mix_h_mass(y: &[f64; NS_GRI30], t: f64) -> f64 {
    let mut total = 0.0;
    for (s, mass) in y.iter().enumerate() {
        if *mass != 0.0 {
            total += mass * h_mass(s, t);
        }
    }
    total
}

/// the dimension of the species vector, so callers can size their
/// buffers without importing the generated table.
pub const NS: usize = NS_GRI30;

#[cfg(test)]
mod tests {
    use super::*;

    /// the formation enthalpy implied by the polynomial at 298.15 K,
    /// J/kg, for the species the tables are most likely to mistype.
    #[test]
    fn formation_enthalpies_match_the_mechanism() {
        // methane's published formation enthalpy is -74.6 kJ/mol.
        let index = species_index("CH4").expect("methane");
        let mass = molar_mass(index);
        let h = h_mass(index, 298.15) * mass / 1000.0;
        assert!(
            (h + 74_600.0).abs() < 800.0,
            "CH4 formation enthalpy {} J/mol",
            h
        );

        // water's is -241.8 kJ/mol.
        let index = species_index("H2O").expect("water");
        let h = h_mass(index, 298.15) * molar_mass(index) / 1000.0;
        assert!(
            (h + 241_820.0).abs() < 800.0,
            "H2O formation enthalpy {} J/mol",
            h
        );
    }

    /// every species' mass must be the sum of its atoms, so that
    /// omega conserves mass to machine precision.
    #[test]
    fn molar_masses_follow_from_the_composition() {
        let weights = [1.008, 12.011, 14.007, 15.999, 39.948];
        for (s, composition) in crate::gri30_thermo::COMPOSITION.iter().enumerate() {
            let composed: f64 = composition
                .iter()
                .zip(weights.iter())
                .map(|(count, weight)| count * weight)
                .sum();
            assert!(
                (composed - molar_mass(s)).abs() < 1e-9,
                "{}: composed {:.9} vs table {:.9}",
                SPECIES_NAMES[s],
                composed,
                molar_mass(s)
            );
        }
    }

    /// cp must be continuous across the switch temperature, since the
    /// fits meet there.
    #[test]
    fn cp_is_continuous_at_the_switch_temperature() {
        for s in 0..NS_GRI30 {
            let switch = TEMPERATURE_RANGES[s][1];
            let below = cp_r(s, switch - 1e-6);
            let above = cp_r(s, switch + 1e-6);
            assert!(
                (below - above).abs() < 1e-3,
                "{}: cp jumps {} at the switch",
                SPECIES_NAMES[s],
                above - below
            );
        }
    }

    /// the species names must be unique, or the index lookup lies.
    #[test]
    fn species_names_are_unique() {
        for (index, name) in SPECIES_NAMES.iter().enumerate() {
            assert_eq!(species_index(name), Some(index), "{}", name);
        }
    }

    /// the polynomial table must reproduce cantera's own evaluation of
    /// the mechanism at every checkpoint: cp, enthalpy and entropy, for
    /// all fifty-three species at five temperatures spanning the fits.
    ///
    /// this is the transcription check. the generator copied the
    /// coefficients; this test says they arrived intact and that the
    /// evaluators interpret them the way the reference does.
    #[test]
    fn the_polynomials_reproduce_cantera() {
        let mut worst_cp = 0.0f64;
        let mut worst_h = 0.0f64;
        let mut worst_s = 0.0f64;
        for point in crate::gri30_fixture::CHECKPOINTS.iter() {
            let t = point.temperature;
            let cp = cp_r(point.species, t) * RU_KMOL;
            let h = h_rt(point.species, t) * RU_KMOL * t;
            let s = s_r(point.species, t) * RU_KMOL;

            let cp_error = (cp - point.cp_mole).abs() / point.cp_mole.abs().max(1.0);
            let h_error = (h - point.enthalpy_mole).abs() / point.enthalpy_mole.abs().max(1.0);
            let s_error = (s - point.entropy_mole).abs() / point.entropy_mole.abs().max(1.0);

            assert!(
                cp_error < 1e-10,
                "{} at {} K: cp {} vs cantera {}",
                SPECIES_NAMES[point.species],
                t,
                cp,
                point.cp_mole
            );
            assert!(
                h_error < 1e-10,
                "{} at {} K: h {} vs cantera {}",
                SPECIES_NAMES[point.species],
                t,
                h,
                point.enthalpy_mole
            );
            assert!(
                s_error < 1e-10,
                "{} at {} K: s {} vs cantera {}",
                SPECIES_NAMES[point.species],
                t,
                s,
                point.entropy_mole
            );
            worst_cp = worst_cp.max(cp_error);
            worst_h = worst_h.max(h_error);
            worst_s = worst_s.max(s_error);
        }
        assert!(worst_cp > 0.0 || worst_h > 0.0 || worst_s > 0.0);
    }
}
